import{_ as n,o as s,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"La Théorie des Plans et la Classification","description":"","frontmatter":{},"headers":[],"relativePath":"fr/80-位面理论与分类.md","filePath":"fr/80-位面理论与分类.md","lastUpdated":null}'),a={name:"fr/80-位面理论与分类.md"};function l(r,e,o,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="la-theorie-des-plans-et-la-classification" tabindex="-1">La Théorie des Plans et la Classification <a class="header-anchor" href="#la-theorie-des-plans-et-la-classification" aria-label="Permalink to &quot;La Théorie des Plans et la Classification&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>80</td></tr><tr><td>Module</td><td>Interaction interplans et règles temporelles</td></tr><tr><td>Mots clés</td><td>théorie des plans, classification des plans, barrières de lois, coordonnées de plans, Univers Hengyuan</td></tr></tbody></table><h2 id="i-la-definition-fondamentale-des-plans" tabindex="-1">I. La Définition Fondamentale des Plans <a class="header-anchor" href="#i-la-definition-fondamentale-des-plans" aria-label="Permalink to &quot;I. La Définition Fondamentale des Plans&quot;">​</a></h2><p>Dans le cadre de l&#39;Univers Originel Wanling Hengmao (Univers Hengyuan), un « plan » désigne une région d&#39;existence délimitée par un ensemble de lois relativement stables, possédant une continuité spatio-temporelle indépendante. Un plan n&#39;est pas simplement « un autre monde », mais une projection concrétisée du réseau des lois dans différents intervalles de paramètres. Chaque plan possède ses constantes physiques uniques, sa densité énergétique, sa vitesse d&#39;écoulement du temps et son niveau d&#39;activité de la conscience, et ces paramètres constituent ensemble « l&#39;empreinte de lois » du plan.</p><p>L&#39;existence des plans provient de la non-uniformité du réseau des lois de l&#39;Univers Hengyuan. Au cours du fonctionnement des lois d&#39;origine de l&#39;univers, en raison des différences de distribution de l&#39;énergie, de perturbation de la conscience et d&#39;évolution historique, d&#39;innombrables régions de lois aux paramètres variés se sont naturellement formées. Ces régions sont séparées par des « barrières de lois », dont la force dépend du degré de différence des paramètres de lois entre plans adjacents — plus la différence est grande, plus la barrière est épaisse, et plus la traversée est difficile.</p><p>Le mécanisme de l&#39;Ancre occupe une position centrale dans la théorie des plans. Une Ancre est essentiellement un nœud stable du réseau des lois ; elle peut non seulement maintenir la stabilité des lois de son propre plan, mais aussi servir de repère d&#39;ancrage pour les connexions interplans. Tous les comportements interactifs tels que la navigation interplans, la communication et l&#39;archéologie doivent utiliser l&#39;Ancre comme origine des coordonnées pour le positionnement et l&#39;étalonnage.</p><h2 id="ii-le-systeme-de-classification-des-plans" tabindex="-1">II. Le Système de Classification des Plans <a class="header-anchor" href="#ii-le-systeme-de-classification-des-plans" aria-label="Permalink to &quot;II. Le Système de Classification des Plans&quot;">​</a></h2><p>Les plans de l&#39;Univers Hengyuan sont divisés en cinq grandes catégories selon les paramètres de lois, les niveaux d&#39;énergie et le degré de développement civilisationnel :</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Caractéristiques de lois</th><th>Densité énergétique</th><th>Forme civilisationnelle typique</th><th>Difficulté de navigation</th></tr></thead><tbody><tr><td>Plan à Dominante Matérielle</td><td>Lois physiques dominantes, énergie latente</td><td>Faible</td><td>Civilisation technologique, civilisation de culture débutante</td><td>Faible</td></tr><tr><td>Plan à Énergie Manifestée</td><td>Lois énergétiques semi-manifestes, systèmes de culture matures</td><td>Moyenne</td><td>Civilisation de culture intermédiaire à avancée, civilisation magique</td><td>Moyenne</td></tr><tr><td>Plan à Dominante de Conscience</td><td>Lois de la conscience manifestes, matière modelable par l&#39;esprit</td><td>Élevée</td><td>Civilisation de corps spirituels, civilisation d&#39;agrégat de conscience</td><td>Élevée</td></tr><tr><td>Plan aux Lois Fragmentées</td><td>Lois instables, nombreuses fissures de lois</td><td>Extrêmement élevée et chaotique</td><td>Plans sauvages, plans de ruines</td><td>Extrêmement élevée</td></tr><tr><td>Plan Proche de l&#39;Origine</td><td>Proche des lois d&#39;origine de l&#39;univers, paramètres approchant les limites</td><td>Approchant l&#39;origine</td><td>Civilisation suprême, gardiens de plans</td><td>Limite théorique</td></tr></tbody></table><p>Outre les cinq grandes catégories ci-dessus, il existe aussi certains types de plans spéciaux, notamment : les Plans Miroirs (existences parallèles hautement symétriques en paramètres de lois avec un certain plan), les Plans Intermédiaires (régions de transition situées entre les barrières de lois de deux plans principaux), les Plans Dormants (plans anciens à activité de lois extrêmement faible, presque à l&#39;arrêt) et les Plans Naissants (jeunes plans récemment formés dans le réseau des lois, aux paramètres pas encore stabilisés).</p><h2 id="iii-coordonnees-de-plans-et-principe-de-positionnement" tabindex="-1">III. Coordonnées de Plans et Principe de Positionnement <a class="header-anchor" href="#iii-coordonnees-de-plans-et-principe-de-positionnement" aria-label="Permalink to &quot;III. Coordonnées de Plans et Principe de Positionnement&quot;">​</a></h2><p>La condition préalable de l&#39;interaction interplans est un positionnement précis des plans. L&#39;Univers Hengyuan a établi un « système de coordonnées de plan en quatre dimensions » fondé sur l&#39;Ancre, chaque plan étant déterminé de manière unique par quatre paramètres :</p><ol><li><strong>Code d&#39;empreinte de lois</strong> : identifiant unique généré par hachage des paramètres de lois centraux du plan, d&#39;une longueur de 128 bits.</li><li><strong>Degré d&#39;association à l&#39;Ancre</strong> : la force de connexion entre le plan et le réseau d&#39;Ancres connu, allant de 0 à 1.</li><li><strong>Rapport de vitesse temporelle</strong> : le rapport entre la vitesse temporelle du plan et le temps standard de l&#39;Univers Hengyuan, généralement de 0,1 à 10.</li><li><strong>Nombre de dimensions spatiales</strong> : le nombre de dimensions spatiales perceptibles du plan, généralement de 3 à 11 dimensions.</li></ol><p>Les méthodes d&#39;obtention des coordonnées de plans comprennent : la détection automatique par le réseau de l&#39;Ancre, le retour de signaux de communication interplans, les résidus de coordonnées dans les ruines archéologiques et les enregistrements manuels des navigateurs interplans. Toutes les coordonnées de plans confirmées sont inscrites dans la « Base Centrale des Coordonnées de Plans de l&#39;Univers Hengyuan », gérée de manière unifiée par l&#39;Administration des Plans placée sous l&#39;Assemblée Délibérante de l&#39;Ancre.</p><h2 id="iv-interactions-naturelles-entre-les-plans" tabindex="-1">IV. Interactions Naturelles Entre les Plans <a class="header-anchor" href="#iv-interactions-naturelles-entre-les-plans" aria-label="Permalink to &quot;IV. Interactions Naturelles Entre les Plans&quot;">​</a></h2><p>Même sans navigation active, des phénomènes d&#39;interaction naturelle existent entre les plans. Le plus courant est « l&#39;infiltration des lois » — en raison de barrières localement faibles entre plans adjacents, un petit nombre de paramètres de lois s&#39;infiltrent mutuellement, provoquant des phénomènes anormaux locaux. Par exemple, les « événements surnaturels » apparaissant occasionnellement dans les plans à dominante matérielle sont souvent causés par l&#39;infiltration des lois d&#39;un plan à énergie manifestée voisin.</p><p>Une autre interaction naturelle est la « résonance de plans ». Lorsque les codes d&#39;empreinte de lois de deux plans présentent un degré élevé de similarité, une résonance de lois périodique se produit entre eux, se manifestant par l&#39;apparition dans les deux plans, pendant des périodes spécifiques, d&#39;événements historiques similaires, de trajectoires civilisationnelles similaires et même de destins personnels similaires. La résonance de plans est un sujet de recherche important de l&#39;archéologie des plans ; en analysant les schémas de résonance, on peut déduire l&#39;état civilisationnel de plans inconnus.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La théorie des plans est la pierre angulaire théorique de toutes les pratiques d&#39;interaction interplans. Comprendre avec précision l&#39;essence, la classification et les principes de positionnement des plans est la condition préalable à l&#39;élaboration des règles de navigation, des normes éthiques et des mécanismes de prévention et de contrôle. L&#39;exploration des plans de l&#39;Univers Hengyuan suit toujours le principe de « la cognition d&#39;abord, l&#39;interaction avec prudence », garantissant que, tout en élargissant les frontières de la civilisation, aucune interférence irréversible ne soit causée à l&#39;évolution autonome d&#39;aucun plan.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Les Règles de Navigation Interplans)</li><li>88-跨位面伦理准则 (Les Normes Éthiques Interplans)</li><li>28-跨位面锚点连接 (Les Connexions Interplans de l&#39;Ancre)</li></ul>',21)])])}const h=n(a,[["render",l]]);export{m as __pageData,h as default};
